//! Cross-language interop: containers encoded by the C# port
//! (tests/NpvTunnel.Core.Tests) decode byte-exactly here.
//!
//! The fixtures carry obviously-fake credentials; committing them makes the
//! interop contract explicit in both implementations. The C# suite decodes
//! the Rust fixtures in return (vectors generated by
//! `cargo run --example genvec`).

use npvt_core::npvt::v2::{decode, peek_lock, Unlock};

#[test]
fn decodes_csharp_open_container() {
    let bytes = include_bytes!("fixtures/csharp-open.npvt2");
    assert_eq!(peek_lock(bytes).expect("peek"), "open");
    let decoded = decode(bytes, Unlock::Any).expect("decode open");
    assert_eq!(decoded.profile.id, "0123abcd0123abcd");
    assert_eq!(decoded.profile.name, "shop bundle");
    assert_eq!(decoded.profile.server, "shop.example.com");
    assert_eq!(decoded.profile.port, 443);
    assert!(decoded.verification.signed);
    assert!(decoded.verification.valid);
}

#[test]
fn decodes_csharp_passphrase_container() {
    let bytes = include_bytes!("fixtures/csharp-passphrase.npvt2");
    assert_eq!(peek_lock(bytes).expect("peek"), "passphrase");
    let decoded = decode(bytes, Unlock::Passphrase("correct horse")).expect("decode");
    assert_eq!(decoded.profile.id, "0123abcd0123abcd");
    assert!(decoded.verification.signed);
    assert!(decoded.verification.valid);
}

#[test]
fn wrong_passphrase_on_csharp_container_fails_closed() {
    let bytes = include_bytes!("fixtures/csharp-passphrase.npvt2");
    let err = decode(bytes, Unlock::Passphrase("wrong")).expect_err("must fail");
    assert!(matches!(err, npvt_core::Error::CryptoAuth));
}
